/**
 * @method
 * @name setCode
 * @description 코드 셋팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    let vLdMktTpCd;

    // 공시유보유형 리스트  셋팅
    const sbmOptions = {
        id : "sbm_dts_ReservTp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_ReservTp=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (scwin.gDoc_LdMktTp === '3') {
        // 선물시장일땐 코스닥기준으로 가져온다.
        vLdMktTpCd = '2';
    } else {
        vLdMktTpCd = scwin.gLdMktTpCd;
    }

    // 공시유보사유 리스트 셋팅
    const sbmOptions2 = {
        id : "sbm_dts_ReservRsn",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_ReservRsn=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 부모창의 데이타 셋팅하기
    scwin.setParamData();
};

/**
 * @method
 * @name modifyReserv
 * @description 유보사유 수정처리하기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modifyReserv = async function() {
    const vTp = cmb_ReservTp.getValue();
    if (scwin.gLdMktTpCd === 1 && vTp.length < 1) {
        await $c.win.alert("유보 유형을 선택하시오.");
        cmb_ReservTp.focus();
        return;
    }

    // 유보사유코드 셋팅
    let vRsnCd1 = '';
    let vRsnCd2 = '';
    let vRsnCd = '';
    vRsnCd1 = cmb_ReservRsn_1.getValue();
    vRsnCd2 = cmb_ReservRsn_2.getValue();
    if (vRsnCd1.length < 1) {
        await $c.win.alert("유보 사유유형을 선택하시오.");
        cmb_ReservRsn_1.focus();
        return;
    }
    if (scwin.gDoc_LdMktTp === '1') {
        // 유가일때
        if (vRsnCd1 === '02' && vRsnCd2.length < 1) {
            await $c.win.alert("유보 사유 유형의 중분류 선택하시오.");
            cmb_ReservRsn_2.focus();
            return;
        }
    } else {
        if (vRsnCd1 === '03' && vRsnCd2.length < 1) {
            await $c.win.alert("유보 사유 유형의 중분류 선택하시오.");
            cmb_ReservRsn_2.focus();
            return;
        }
    }
    if (vRsnCd2.length === 4) {
        vRsnCd = vRsnCd2;
    } else {
        vRsnCd = vRsnCd1;
    }
    const vRsnContn = txa_ReservRsnContn.getValue();
    if ($c.stf.checkMaxLength(txa_ReservRsnContn, 500, '유보사유') === false) {
        return;
    }
    let vRedisclsYn;
    if (rdo_rediscls_yn.getValue() === '1') {
        vRedisclsYn = 'Y';
    } else {
        vRedisclsYn = 'N';
    }
    // 코스닥일 경우만 체크
    if (scwin.gDoc_LdMktTp === '2' || scwin.gDoc_LdMktTp === '6') {
        if (vRedisclsYn === 'Y' &&
            (txb_rediscls_acptno.getValue() === "" || txb_rediscls_acptno.getValue() === "-")) {
            await $c.win.alert("재공시유무에 '예'를 선택하셨을 경우에는 반드시 재공시를 선택하셔야 합니다.");
            return false;
        }
        if (vRedisclsYn === 'N' &&
            (txb_rediscls_acptno.getValue() !== "" && txb_rediscls_acptno.getValue() !== "-")) {
            await $c.win.alert("재공시를 선택하셨을 경우에는 재공시유무에 '예'를 선택하셔야 합니다.");
            rdo_rediscls_yn.focus();
            return false;
        }
    }
    if (scwin.gAcptNo === '') {
        await $c.win.alert("접수정보를 다시 읽어와야 하므로 창을 닫으신후 다시 열어 주세요.");
        return false;
    }
    dts_ReservInfo.insertRow();
    dts_ReservInfo.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_ReservInfo.setCellData(1, "LDMKTTP_CD", scwin.gLdMktTpCd);
    dts_ReservInfo.setCellData(1, "RESERV_TP_CD", vTp);
    dts_ReservInfo.setCellData(1, "DISCLS_RESERV_RSN_CD", vRsnCd);
    dts_ReservInfo.setCellData(1, "DISCLS_PROCS_RSN_DTL_CONTN", vRsnContn);
    dts_ReservInfo.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_ReservInfo.setCellData(1, "DISCLS_PROCS_SEQ", scwin.gProcsSeq);
    dts_ReservInfo.setCellData(1, "REDISCLS_YN", vRedisclsYn);
    dts_ReservInfo.setCellData(1, "REDISCLS_ACPT_NO", txb_rediscls_acptno.getValue());
    if (dts_ReservInfo.getCellData(1, "ACPT_NO") === '') {
        await $c.win.alert("접수정보를 다시 읽어와야 하므로 창을 닫으신후 다시 열어 주세요.");
        return false;
    }
    const vAnswer = confirm(scwin.gStatTitle + '사유 수정처리 하시겠습니까?');
    if (vAnswer === true) {
        trs_Reserv.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Reserv",
            action : "/DisclosureApproval.do",
            ref : "dts_ReservInfo",
            target : "trs_Reserv=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name dts_procs_stat_OnLoadCompleted
 * @description dts_procs_stat 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
