 */
scwin.btn_Close_onclick = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    await scwin.modifyReserv();
};

/**
 * @method
 * @name trs_Reserv_OnSuccess
 * @description Reserv On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Reserv_OnSuccess = async function() {
    await $c.win.alert("성공적으로 수정처리 되었습니다.");

    // 부모창 reload 처리해야함
    $c.frame.path("../").fn_Search();
    await $c.win.closePopup();
};

/**
 * @method
 * @name trs_Reserv_OnFail
 * @description Reserv On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Reserv_OnFail = async function() {
    await $c.win.alert('trs_Reserv.OnFail() :' + trs_Reserv.ErrorMsg);
};

/**
 * @method
 * @name dts_ReservRsn_OnLoadCompleted
 * @description 데이터셋 복사
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ReservRsn_OnLoadCompleted = async function(rowcount) {
    // 데이터셋 복사
    $c.stf.copyDataSet(dts_ReservRsn, dts_ReservRsn1);
    $c.stf.copyDataSet(dts_ReservRsn, dts_ReservRsn2);
    dts_ReservRsn1.UseFilter = true;
    dts_ReservRsn1.Filter();

    // 유보사유 읽어오기
    const sbmOptions = {
        id : "sbm_dts_ReservRead",
        action : "/DisclosureStatus.do",
        ref : "",
        target : "dts_ReservRead=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name dts_ReservRsn2_OnLoadCompleted
 * @description dts_ReservRsn2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ReservRsn2_OnLoadCompleted = function(rowcount) {

};

/**
 * @method
 * @name dts_ReservRsn1_OnFilter
 * @description Reserv Rsn1 On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_ReservRsn1_OnFilter = function(row) {
    if (dts_ReservRsn1.getCellData(row, "value").length === 2) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name cmb_ReservRsn_1_onselchange2
 * @description cmb Reserv Rsn 1 onselchange2 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_ReservRsn_1_onselchange2 = function() {
    scwin.gRscCd1 = $c.cp.valueOfIndex(cmb_ReservRsn_1, "value", cmb_ReservRsn_1.getSelectedIndex());
    dts_ReservRsn2.UseFilter = true;
    dts_ReservRsn2.Filter();

    // 유보사유 중분류 선택할 값이 있으면 enable
    if (dts_ReservRsn2.getRowCount() > 0) {
        cmb_ReservRsn_2.setDisabled(false);
        cmb_ReservRsn_2.trigger("onclick");
    } else {
        cmb_ReservRsn_2.setDisabled(true);
    }
};

/**
 * @method
 * @name cmb_ReservRsn_1_OnSelected
 * @description cmb Reserv Rsn 1 On Selected 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_ReservRsn_1_OnSelected = function() {

};

/**
 * @method
 * @name dts_ReservRsn2_OnFilter
 * @description 대분류에 해당하는 중분류를 가져온다.
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_ReservRsn2_OnFilter = function(row) {
    //  대분류에 해당하는 중분류를 가져온다.
    if (dts_ReservRsn2.getCellData(row, "value").substr(0, 2) === scwin.gRscCd1 &&
        dts_ReservRsn2.getCellData(row, "value").length === 4) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name dts_ReservRead_OnLoadCompleted
 * @description dts_ReservRead 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ReservRead_OnLoadCompleted = function(rowcount) {
    scwin.gRscCd1 = dts_ReservRead.getCellData(1, "RESERV_RSN_CD1");
    scwin.gProcsSeq = dts_ReservRead.getCellData(1, "DISCLS_PROCS_SEQ");
    dts_ReservRsn2.UseFilter = true;
    dts_ReservRsn2.Filter();
    scwin.gDRsnCd2 = dts_ReservRead.getCellData(1, "RESERV_RSN_CD2");
    if (scwin.gDRsnCd2 === null || scwin.gDRsnCd2 === '') {
        cmb_ReservRsn_2.setDisabled(true);
    } else {
        cmb_ReservRsn_2.setValue(scwin.gDRsnCd2);
        cmb_ReservRsn_2.setDisabled(false);
    }
    rdo_rediscls_yn.setValue(dts_ReservRead.getCellData(1, "REDISCLS_YN"));
    txb_rediscls_acptno.setValue(dts_ReservRead.getCellData(1, "REDISCLS_ACPT_NO"));
    txb_acpt_ddtm.setValue(dts_ReservRead.getCellData(1, "REDISCLS_PROCS_DDTM"));
    txb_doc_title.setValue(dts_ReservRead.getCellData(1, "REDISCLS_DOC_TITLE"));
};

/**
 * @method
 * @name dts_AcptProcs_OnLoadCompleted
 * @description *** 처리일시 타이틀 셋팅
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_AcptProcs_OnLoadCompleted = function(rowcount) {
    // *** 처리일시 타이틀 셋팅
    txb_ProcsStatDdtm_Title.setValue(txb_ProcsStatNm.getValue() + " 처리일시");
    scwin.gLdMktTpCd = dts_AcptProcs.getCellData(1, "LD_MKT_TP_CD");
    scwin.gIsurCd = dts_AcptProcs.getCellData(1, "ISUR_CD");
    if (scwin.gLdMktTpCd === '1') {
        cmb_ReservTp.setDisabled(false);
        label_noti.hide();
    } else {
        cmb_ReservTp.setDisabled(true);
        label_noti.show("");
    }
};

/**
 * @method
 * @name dts_ReservRead_OnLoadError
 * @description dts_ReservRead 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ReservRead_OnLoadError = async function() {
    await $c.win.alert('dts_ReservRead.OnLoadError()');
};

/**
 * @method
 * @name img_search_onclick
 * @description img_search 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_search_onclick = async function() {
    const url = "/dsclproc/ULDSTF10011.gfm";
    const winTitle = " 공시 제출현황";
    // frame.CreateDialogFrame("DSCLLIST"+gIsurCd, url , winTitle ,100, 10, 620, 430+30, "window" );
    await $c.frame.CreateFrame("DSCLLIST" + scwin.gIsurCd, url, winTitle, 100, 10, 620, 430 + 30, "window", 0, 0, true);
};

/**
 * @method
 * @name rdo_rediscls_yn_onselchange
 * @description rdo_rediscls_yn onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_rediscls_yn_onselchange = function() {
    if (rdo_rediscls_yn.getValue() === 2) {
        txb_acpt_ddtm.setValue("");
        txb_doc_title.setValue("");
        txb_rediscls_acptno.setValue("");
    }
};

/**
 * @method
 * @name txb_doc_title_onclick
 * @description txb_doc_title 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_doc_title_onclick = async function() {
    const rAcptno = txb_rediscls_acptno.getValue();
    if (rAcptno !== "") {
        await $c.stf.openDisclViewer(rAcptno, "R");
    }
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(pnl_1);
    await scwin.setCode();
    // 가우스헤더 셋팅
    const sbmOptions = {
        id : "sbm_dts_ReservInfo",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_ReservInfo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    cmb_ReservRsn_2.setDisabled(true);
    txb_rediscls_acptno.hide();
};
